import json, csv, os
from collections import defaultdict

# ── 1. Parse instance ────────────────────────────────────────────────────
allowed = {}
with open("/app/data/instance.txt") as f:
    first = f.readline().split()
    n_jobs, n_machines = int(first[0]), int(first[1])
    for j in range(n_jobs):
        n_ops = int(f.readline().strip())
        for o in range(n_ops):
            parts = list(map(int, f.readline().split()))
            n_alt = parts[0]
            alts = {}
            for k in range(n_alt):
                m = parts[1 + 2*k]
                d = parts[1 + 2*k + 1]
                alts[m] = d
            allowed[(j,o)] = alts

# ── 2. Parse downtime ────────────────────────────────────────────────────
downtime = {}
with open("/app/data/downtime.csv") as f:
    reader = csv.DictReader(f)
    for row in reader:
        m = int(row["machine"])
        s = int(row["start"])
        e = int(row["end"])
        downtime.setdefault(m, []).append((s, e))
for m in downtime:
    downtime[m].sort()

# ── 3. Parse policy ──────────────────────────────────────────────────────
with open("/app/data/policy.json") as f:
    policy = json.load(f)

freeze_enabled = policy["freeze"]["enabled"]
freeze_until = policy["freeze"]["freeze_until"]
lock_fields = policy["freeze"]["lock_fields"]
max_mc = policy["change_budget"]["max_machine_changes"]
max_shift_l1 = policy["change_budget"]["max_total_start_shift_L1"]

# ── 4. Parse baseline ────────────────────────────────────────────────────
with open("/app/data/baseline_solution.json") as f:
    baseline = json.load(f)

base_list = baseline["schedule"]
base_map = {(r["job"], r["op"]): r for r in base_list}
base_index = {(r["job"], r["op"]): i for i, r in enumerate(base_list)}

# ── 5. Helper functions ──────────────────────────────────────────────────
def overlap(s, e, a, b):
    return s < b and a < e

def has_conflict(m, st, en, machine_intervals, downtime):
    for a, b in machine_intervals.get(m, []):
        if overlap(st, en, a, b):
            return True
    for a, b in downtime.get(m, []):
        if overlap(st, en, a, b):
            return True
    return False

def earliest_feasible_time(m, anchor, dur, machine_intervals, downtime, safety=200000):
    t = int(anchor)
    for _ in range(safety):
        if not has_conflict(m, t, t + dur, machine_intervals, downtime):
            return t
        t += 1
    return t

# ── 6. Precedence-aware order ────────────────────────────────────────────
def precedence_aware_order(base_list):
    base_map_l = {(r["job"], r["op"]): r for r in base_list}
    base_index_l = {(r["job"], r["op"]): i for i, r in enumerate(base_list)}
    keys = list(base_map_l.keys())
    keys.sort(key=lambda k: (k[1], base_map_l[k]["start"], base_index_l[k]))
    return keys

order = precedence_aware_order(base_list)

# ── 7. Identify frozen ops and pre-reserve them ─────────────────────────
# First pass: identify which ops are frozen AND downtime-feasible at baseline position
machine_intervals = {}
frozen_set = set()

if freeze_enabled:
    for (j, o) in order:
        base_rec = base_map[(j, o)]
        if base_rec["start"] < freeze_until:
            m = base_rec["machine"]
            # Check if baseline machine is legal
            if m not in allowed[(j, o)]:
                continue  # Can't freeze with illegal machine
            d = allowed[(j, o)][m]
            st = base_rec["start"]
            en = st + d
            # Check only downtime conflict (not machine_intervals yet since we're pre-reserving)
            dt_conflict = False
            for a, b in downtime.get(m, []):
                if overlap(st, en, a, b):
                    dt_conflict = True
                    break
            if not dt_conflict:
                frozen_set.add((j, o))

# Now check frozen ops don't overlap with each other
frozen_by_machine = defaultdict(list)
for (j, o) in frozen_set:
    base_rec = base_map[(j, o)]
    m = base_rec["machine"]
    d = allowed[(j, o)][m]
    frozen_by_machine[m].append((base_rec["start"], base_rec["start"] + d, j, o))

for m in frozen_by_machine:
    ops = sorted(frozen_by_machine[m])
    for i in range(len(ops) - 1):
        if ops[i][1] > ops[i+1][0]:
            # Overlap between frozen ops; remove the later one from frozen set
            frozen_set.discard((ops[i+1][2], ops[i+1][3]))

# Pre-reserve frozen positions
for (j, o) in order:
    if (j, o) in frozen_set:
        base_rec = base_map[(j, o)]
        m = base_rec["machine"]
        d = allowed[(j, o)][m]
        st = base_rec["start"]
        en = st + d
        machine_intervals.setdefault(m, []).append((st, en))

print(f"Frozen operations: {sorted(frozen_set)}")

# ── 8. Repair algorithm ─────────────────────────────────────────────────
new_schedule = {}

mc_used = 0
shift_used = 0

THRESH = 6

for (j, o) in order:
    base_rec = base_map[(j, o)]
    base_start = base_rec["start"]
    base_m_orig = base_rec["machine"]

    # If frozen, just place it at baseline position
    if (j, o) in frozen_set:
        m = base_rec["machine"]
        d = allowed[(j, o)][m]
        st = base_rec["start"]
        en = st + d
        new_schedule[(j, o)] = {
            "job": j, "op": o, "machine": m,
            "start": st, "end": en, "dur": d
        }
        # Already in machine_intervals from pre-reservation
        # No machine change or shift
        continue

    # Anchor: max(base_start, end of previous op of same job in new schedule)
    if o > 0 and (j, o-1) in new_schedule:
        prev_end = new_schedule[(j, o-1)]["end"]
    else:
        prev_end = 0
    anchor = max(base_start, prev_end)

    # Determine baseline machine (may need correction if illegal)
    base_m = base_m_orig
    if base_m not in allowed[(j, o)]:
        base_m = min(allowed[(j, o)], key=lambda mm: allowed[(j, o)][mm])

    # Try baseline machine first
    base_d = allowed[(j, o)][base_m]
    cand_st = earliest_feasible_time(base_m, anchor, base_d, machine_intervals, downtime)
    best_st = cand_st
    best_m = base_m
    best_d = base_d

    # If shift is large and we have machine-change budget, consider alternates
    if (cand_st - base_rec["start"]) >= THRESH and mc_used < max_mc:
        for mm in allowed[(j, o)]:
            dd = allowed[(j, o)][mm]
            st = earliest_feasible_time(mm, anchor, dd, machine_intervals, downtime)
            mc_change = int(mm != base_m_orig)

            if mc_used + mc_change > max_mc:
                continue

            if st < best_st:
                best_st = st
                best_m = mm
                best_d = dd

    # Record
    new_schedule[(j, o)] = {
        "job": j, "op": o, "machine": best_m,
        "start": best_st, "end": best_st + best_d, "dur": best_d
    }
    machine_intervals.setdefault(best_m, []).append((best_st, best_st + best_d))
    mc_used += int(best_m != base_m_orig)
    shift_used += abs(best_st - base_rec["start"])

# ── 9. Compute makespan ─────────────────────────────────────────────────
makespan = max(r["end"] for r in new_schedule.values())

# ── 10. Validation ───────────────────────────────────────────────────────
print("\n=== Validation ===")
print(f"Makespan: {makespan}  (baseline: {baseline['makespan']})")
print(f"Machine changes: {mc_used} / {max_mc}")
print(f"Total L1 start shift: {shift_used} / {max_shift_l1}")

errors = 0

# Check precedence
for (j,o), rec in new_schedule.items():
    if o > 0:
        prev = new_schedule[(j, o-1)]
        if prev["end"] > rec["start"]:
            print(f"  PRECEDENCE VIOLATION: job {j} op {o-1} ends {prev['end']} > op {o} starts {rec['start']}")
            errors += 1

# Check machine overlaps
by_machine = defaultdict(list)
for rec in new_schedule.values():
    by_machine[rec["machine"]].append(rec)
for m, ops in by_machine.items():
    ops_sorted = sorted(ops, key=lambda r: r["start"])
    for i in range(len(ops_sorted)-1):
        if ops_sorted[i]["end"] > ops_sorted[i+1]["start"]:
            print(f"  MACHINE OVERLAP: machine {m}: ({ops_sorted[i]['job']},{ops_sorted[i]['op']}) ends {ops_sorted[i]['end']} > ({ops_sorted[i+1]['job']},{ops_sorted[i+1]['op']}) starts {ops_sorted[i+1]['start']}")
            errors += 1

# Check downtime
for rec in new_schedule.values():
    m = rec["machine"]
    for ds, de in downtime.get(m, []):
        if overlap(rec["start"], rec["end"], ds, de):
            print(f"  DOWNTIME VIOLATION: job {rec['job']} op {rec['op']} [{rec['start']},{rec['end']}) on machine {m} overlaps downtime [{ds},{de})")
            errors += 1

# Check allowed machines
for (j, o), rec in new_schedule.items():
    if rec["machine"] not in allowed[(j, o)]:
        print(f"  ILLEGAL MACHINE: job {j} op {o} on machine {rec['machine']}, allowed: {allowed[(j,o)]}")
        errors += 1
    elif rec["dur"] != allowed[(j, o)][rec["machine"]]:
        print(f"  WRONG DURATION: job {j} op {o} dur {rec['dur']} but should be {allowed[(j,o)][rec['machine']]} on machine {rec['machine']}")
        errors += 1

# Check freeze
if freeze_enabled:
    for (j, o), rec in new_schedule.items():
        base_rec = base_map[(j, o)]
        if base_rec["start"] < freeze_until:
            for field in lock_fields:
                if field == "dur":
                    continue
                if rec[field] != base_rec[field]:
                    if field == "machine" and base_rec["machine"] not in allowed[(j,o)]:
                        continue
                    if field == "end":
                        # end may differ if dur differs due to machine change needed
                        if base_rec["machine"] not in allowed[(j,o)]:
                            continue
                    # Check if this was a downtime-forced change
                    m_b = base_rec["machine"]
                    if m_b in allowed[(j,o)]:
                        d_b = allowed[(j,o)][m_b]
                        dt_conflict = False
                        for a, b in downtime.get(m_b, []):
                            if overlap(base_rec["start"], base_rec["start"]+d_b, a, b):
                                dt_conflict = True
                                break
                        if dt_conflict:
                            print(f"  FREEZE NOTE (downtime-forced): job {j} op {o} field '{field}' changed: {base_rec[field]} -> {rec[field]}")
                            continue
                    print(f"  FREEZE VIOLATION: job {j} op {o} field '{field}' changed: {base_rec[field]} -> {rec[field]}")
                    errors += 1

if errors == 0:
    print("  No violations found!")

print("=== Validation complete ===")

# Print detailed schedule
print("\n=== Schedule ===")
for (j, o) in sorted(new_schedule.keys()):
    r = new_schedule[(j, o)]
    b = base_map[(j, o)]
    changed_m = " (M-CHG)" if r["machine"] != b["machine"] else ""
    shifted = f" (shift={r['start']-b['start']})" if r["start"] != b["start"] else ""
    frz = " [FROZEN]" if (j,o) in frozen_set else ""
    print(f"  Job {j} Op {o}: machine={r['machine']}, start={r['start']}, end={r['end']}, dur={r['dur']}{changed_m}{shifted}{frz}")

# ── 11. Output ───────────────────────────────────────────────────────────
os.makedirs("/app/output", exist_ok=True)

schedule_list = sorted(new_schedule.values(), key=lambda r: (r["start"], r["job"], r["op"]))

solution = {
    "status": "REPAIRED",
    "makespan": makespan,
    "schedule": schedule_list
}

with open("/app/output/solution.json", "w") as f:
    json.dump(solution, f, indent=2)

with open("/app/output/schedule.csv", "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=["job", "op", "machine", "start", "end", "dur"])
    writer.writeheader()
    for rec in schedule_list:
        writer.writerow(rec)

print(f"\nOutput written to /app/output/solution.json and /app/output/schedule.csv")

