    for (j, o) in order:
        if (j, o) in frozen_set:
            base_rec = base_map[(j, o)]
            m = base_rec["machine"]
            d = allowed[(j, o)][m]
            st = base_rec["start"]
            en = st + d
            machine_intervals.setdefault(m, []).append((st, en))

    new_schedule = {}
    mc_used = 0
    shift_used = 0

    for (j, o) in order:
        base_rec = base_map[(j, o)]
        base_start = base_rec["start"]
        base_m_orig = base_rec["machine"]

        if (j, o) in frozen_set:
            m = base_rec["machine"]
            d = allowed[(j, o)][m]
            st = base_rec["start"]
            en = st + d
            new_schedule[(j, o)] = {
                "job": j, "op": o, "machine": m,
                "start": st, "end": en, "dur": d
            }
            continue

        if o > 0 and (j, o-1) in new_schedule:
            prev_end = new_schedule[(j, o-1)]["end"]
        else:
            prev_end = 0
        anchor = max(base_start, prev_end)

        base_m = base_m_orig
        if base_m not in allowed[(j, o)]:
            base_m = min(allowed[(j, o)], key=lambda mm: allowed[(j, o)][mm])

        base_d = allowed[(j, o)][base_m]
        cand_st = earliest_feasible_time(base_m, anchor, base_d, machine_intervals, downtime)
        best_st = cand_st
        best_m = base_m
        best_d = base_d

        if (cand_st - base_rec["start"]) >= thresh_val and mc_used < max_mc:
            for mm in allowed[(j, o)]:
                dd = allowed[(j, o)][mm]
                st = earliest_feasible_time(mm, anchor, dd, machine_intervals, downtime)
                mc_change = int(mm != base_m_orig)
                if mc_used + mc_change > max_mc:
                    continue
                if st < best_st:
                    best_st = st
                    best_m = mm
                    best_d = dd

