            base_m = min(allowed[(j, o)], key=lambda mm: allowed[(j, o)][mm])

        base_d = allowed[(j, o)][base_m]
        cand_st = earliest_feasible_time(base_m, anchor, base_d, machine_intervals, downtime)
        best_st = cand_st
        best_m = base_m
        best_d = base_d

        if (cand_st - base_rec["start"]) >= thresh_val and mc_used < max_mc:
            for mm in allowed[(j, o)]:
                dd = allowed[(j, o)][mm]
                st = earliest_feasible_time(mm, anchor, dd, machine_intervals, downtime)
                mc_change = int(mm != base_m_orig)
                if mc_used + mc_change > max_mc:
                    continue
                if st < best_st:
                    best_st = st
                    best_m = mm
                    best_d = dd

        new_schedule[(j, o)] = {
            "job": j, "op": o, "machine": best_m,
            "start": best_st, "end": best_st + best_d, "dur": best_d
        }
        machine_intervals.setdefault(best_m, []).append((best_st, best_st + best_d))
        mc_used += int(best_m != base_m_orig)
        shift_used += abs(best_st - base_rec["start"])

    makespan = max(r["end"] for r in new_schedule.values())
    return new_schedule, makespan, mc_used, shift_used

# Try different thresholds
best_result = None
best_makespan = float('inf')
for thresh in range(0, 20):
    sched, ms, mc, shift = run_repair(thresh)
    if mc <= max_mc and shift <= max_shift_l1 and ms < best_makespan:
        best_makespan = ms
        best_result = (sched, ms, mc, shift, thresh)

print(f"\nBest threshold: {best_result[4]}, makespan: {best_result[1]}, mc: {best_result[2]}, shift: {best_result[3]}")

new_schedule, makespan, mc_used, shift_used = best_result[0], best_result[1], best_result[2], best_result[3]

# ── 10. Validation ───────────────────────────────────────────────────────
print("\n=== Validation ===")
print(f"Makespan: {makespan}  (baseline: {baseline['makespan']})")
print(f"Machine changes: {mc_used} / {max_mc}")
print(f"Total L1 start shift: {shift_used} / {max_shift_l1}")

errors = 0

for (j,o), rec in new_schedule.items():
    if o > 0:
        prev = new_schedule[(j, o-1)]
        if prev["end"] > rec["start"]:
            print(f"  PRECEDENCE VIOLATION: job {j} op {o-1} ends {prev['end']} > op {o} starts {rec['start']}")
            errors += 1

by_machine = defaultdict(list)
for rec in new_schedule.values():
    by_machine[rec["machine"]].append(rec)
for m, ops in by_machine.items():
    ops_sorted = sorted(ops, key=lambda r: r["start"])
    for i in range(len(ops_sorted)-1):
        if ops_sorted[i]["end"] > ops_sorted[i+1]["start"]:
            print(f"  MACHINE OVERLAP: machine {m}: ({ops_sorted[i]['job']},{ops_sorted[i]['op']}) ends {ops_sorted[i]['end']} > ({ops_sorted[i+1]['job']},{ops_sorted[i+1]['op']}) starts {ops_sorted[i+1]['start']}")
            errors += 1

for rec in new_schedule.values():
    m = rec["machine"]
    for ds, de in downtime.get(m, []):
        if overlap(rec["start"], rec["end"], ds, de):
            print(f"  DOWNTIME VIOLATION: job {rec['job']} op {rec['op']} [{rec['start']},{rec['end']}) on machine {m} overlaps downtime [{ds},{de})")
            errors += 1

for (j, o), rec in new_schedule.items():
    if rec["machine"] not in allowed[(j, o)]:
        print(f"  ILLEGAL MACHINE: job {j} op {o} on machine {rec['machine']}, allowed: {allowed[(j,o)]}")
        errors += 1
    elif rec["dur"] != allowed[(j, o)][rec["machine"]]:
        print(f"  WRONG DURATION: job {j} op {o} dur {rec['dur']} but should be {allowed[(j,o)][rec['machine']]} on machine {rec['machine']}")
        errors += 1

# Check start >= baseline start (never start earlier)
for (j, o), rec in new_schedule.items():
    base_rec = base_map[(j, o)]
    if rec["start"] < base_rec["start"]:
        print(f"  EARLY START: job {j} op {o} starts at {rec['start']} < baseline {base_rec['start']}")
        errors += 1

if freeze_enabled:
    for (j, o), rec in new_schedule.items():
        base_rec = base_map[(j, o)]
        if base_rec["start"] < freeze_until:
            for field in lock_fields:
                if field == "dur":
                    continue
                if rec[field] != base_rec[field]:
                    if field == "machine" and base_rec["machine"] not in allowed[(j,o)]:
                        continue
                    if field == "end" and base_rec["machine"] not in allowed[(j,o)]:
                        continue
                    m_b = base_rec["machine"]
                    if m_b in allowed[(j,o)]:
                        d_b = allowed[(j,o)][m_b]
                        dt_conflict = False
                        for a, b in downtime.get(m_b, []):
                            if overlap(base_rec["start"], base_rec["start"]+d_b, a, b):
                                dt_conflict = True
                                break
                        if dt_conflict:
                            continue
                    print(f"  FREEZE VIOLATION: job {j} op {o} field '{field}' changed: {base_rec[field]} -> {rec[field]}")
                    errors += 1

if errors == 0:
    print("  No violations found!")
else:
    print(f"  Total violations: {errors}")

print("=== Validation complete ===")

print("\n=== Schedule ===")
for (j, o) in sorted(new_schedule.keys()):
    r = new_schedule[(j, o)]
    b = base_map[(j, o)]
    changed_m = " (M-CHG)" if r["machine"] != b["machine"] else ""
    shifted = f" (shift={r['start']-b['start']})" if r["start"] != b["start"] else ""
    frz = " [FROZEN]" if (j,o) in frozen_set else ""
    print(f"  Job {j} Op {o}: machine={r['machine']}, start={r['start']}, end={r['end']}, dur={r['dur']}{changed_m}{shifted}{frz}")

# ── 11. Output ───────────────────────────────────────────────────────────
os.makedirs("/app/output", exist_ok=True)

schedule_list = sorted(new_schedule.values(), key=lambda r: (r["start"], r["job"], r["op"]))

solution = {
    "status": "REPAIRED",
    "makespan": makespan,
    "schedule": schedule_list
}

with open("/app/output/solution.json", "w") as f:
    json.dump(solution, f, indent=2)

with open("/app/output/schedule.csv", "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=["job", "op", "machine", "start", "end", "dur"])
    writer.writeheader()
    for rec in schedule_list:
        writer.writerow(rec)

print(f"\nOutput written to /app/output/solution.json and /app/output/schedule.csv")
